// Function shapes: `out` parameters, a return type, SelfContained; GLSL type and intrinsic spellings inside bodies
// are rewritten, each recorded as a rename.
/// @custom
void Remap01(float value, out float result)
{
    result = saturate(value * 0.5 + 0.5);
}

/// @custom
float Luma(float3 color)
{ return dot(color, float3(0.299, 0.587, 0.114)); }

/// @custom selfcontained
void Blend(float3 a, float3 b, float t, out float3 result)
{
    result = lerp(a, b, frac(t));
}
